"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4: per-decision compute time on the laptop (RTX 5060 8 GB) for the local systems (plan 7.5: latency median and
p90, as v0.3's scripts/p1_latency.py).

Each component is timed alone on the same 100 dev windows that have a line (seeded sample), batch 1, after 10 warm-up
decisions, with torch.cuda.synchronize() around each; the audio is already in memory. Per decision only the newest
line is new (the history's transcripts, speaker scores and detections were computed at earlier points), so:
  - front end (every system that reads the situation text): detector on the 8 s window + Whisper-small on the line
    (padded to 30 s, greedy, as the features) + ECAPA on the line;
  - B1-strong = front end (the rule itself is negligible; its chosen setting uses no sentence embedding);
  - B2-local = front end + Qwen3.5-4B with the cached policy + examples prefix (K chosen on dev), one pass per asked
    question (as scripts/p1v4_b2.py: the case, question and label after a copy of the prefix cache; the prompts are
    tokenised before timing, in its favour);
  - L1 = front end + VoxTurn with the new adapter on the situation text (both asked questions in one pass);
  - L2 = front end + the official VoxTurn's five questions + three MiniLM embeddings (line, history, assistant);
  - L3 = front end + whisper-base encoder and head + three MiniLM embeddings.
usage: python -X utf8 scripts/p1v4_latency.py <out.json>
"""
import copy
import json
import os
import random
import sys
import time

import numpy as np
import soundfile as sf
import torch

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402

N, WARM, SR = 100, 10, 16000
R = "data/p1v4/runs"


def timed(fn, xs):
    for x in xs[:WARM]:
        fn(x)
    out = []
    for x in xs[WARM:WARM + N]:
        torch.cuda.synchronize()
        t0 = time.perf_counter()
        fn(x)
        torch.cuda.synchronize()
        out.append(time.perf_counter() - t0)
    return {"median_s": float(np.median(out)), "p90_s": float(np.quantile(out, 0.9)), "n": len(out)}


def free():
    import gc
    gc.collect()
    torch.cuda.empty_cache()


def main(out_path):
    D.gpu_guard()
    import p1v4_l1 as L1
    ex, rows = L1.examples("dev")
    wins, by_key = D.load_windows("dev")
    ctx = C.Context("dev")
    with_line = [i for i, w in enumerate(wins) if by_key[w["key"]]["points"][w["k"]].get("line")]
    sample = random.Random(7).sample(with_line, N + WARM)
    items = []
    for i in sample:
        w = wins[i]
        r = by_key[w["key"]]
        p = r["points"][w["k"]]
        src = {s["id"]: s for s in r["sources"]}[p["line"]]
        x = sf.read(w["path"], dtype="float32")[0]
        w0 = p["t"] - D.WIN_S
        a = int(round(max(0.0, src["start"] - w0) * SR))
        b = int(round((min(src["end"] + 0.2, p["t"]) - w0) * SR))
        tr = ctx.point(r, w["k"])[0]
        text, asks = ctx.situation(r, w["k"], "full")
        items.append({"j": len(items), "i": i, "ex": ex[i], "wave": x, "line_wave": x[a:max(b, a + 1600)],
                      "line_text": tr.get(p["line"], ""),
                      "text": text, "asks": asks, "row": r, "k": w["k"]})
    res, errors = {}, {}

    def run(name, setup):
        try:
            fn = setup()
            res[name] = timed(fn, items)
            print(name, json.dumps(res[name]), flush=True)
        except Exception as e:                              # one component failing does not stop the others
            errors[name] = repr(e)[:500]
            print(name, "FAILED", errors[name], flush=True)
        free()

    # detector
    def setup_det():
        import p1v4_sed as SED
        det = SED.load(f"{R}/sed/sed.pt")

        def f(it):
            xx = torch.from_numpy(SED.to32(it["wave"]))[None].cuda()
            with torch.no_grad(), torch.autocast("cuda", dtype=torch.bfloat16):
                return SED.forward(det, xx)[0]
        return f
    run("detector", setup_det)

    def setup_whisper():
        import p1v4_feats as FE
        wh = FE.Whisper(*FE.WHISPER)
        return lambda it: wh([it["line_wave"]])
    run("whisper_small_line", setup_whisper)

    def setup_ecapa():
        import p1v4_feats as FE
        ec = FE.load_ecapa()

        def f(it):
            with torch.no_grad():
                return ec.encode_batch(torch.from_numpy(it["line_wave"])[None].cuda())
        return f
    run("ecapa_line", setup_ecapa)

    def setup_minilm():
        import p1v4_b1 as B1
        import p1v4_l2 as L2
        from transformers import AutoModel, AutoTokenizer
        tok = AutoTokenizer.from_pretrained(B1.MINILM[0], revision=B1.MINILM[1])
        m = AutoModel.from_pretrained(B1.MINILM[0], revision=B1.MINILM[1]).cuda().eval()

        def f(it):
            texts = [it["line_text"] or "nothing said", L2.history_text(it["text"]), it["text"].split("\n")[0]]
            enc = tok(texts, padding=True, truncation=True, max_length=128, return_tensors="pt").to("cuda")
            with torch.no_grad():
                return m(**enc).last_hidden_state.mean(1)
        return f
    run("minilm_x3", setup_minilm)

    def setup_voxturn5():
        import l1_voxturn
        import p1v4_voxturn as V
        _, vt = l1_voxturn.load_official()
        qs = [(q, 0) for q in V.QUESTIONS]

        def f(it):
            w = torch.from_numpy(it["wave"])[None].cuda()
            return vt.logits(w, [True], [it["line_text"]], [it["ex"]["marker"]], ["en"], [qs])
        return f
    run("voxturn_5q", setup_voxturn5)

    def setup_l1():
        m = L1.build()
        L1.load_new_state(m, torch.load(f"{R}/l1/l1_new.pt", weights_only=True))
        local = [it["ex"] for it in items]

        def f(it):
            w = torch.from_numpy(it["wave"])[None].cuda()
            with torch.no_grad():
                return L1.run(m, local, w, [it["j"]], [0])
        return f
    run("L1", setup_l1)

    def setup_l3():
        import p1v4_l3 as L3
        ck = torch.load(f"{R}/l3/l3.pt", weights_only=False)        # our own file (it holds numpy means)
        dv, _, _, X, _, _ = L3.data("dev", ck["mu"], ck["sd"])
        net = L3.Net(X.shape[1]).cuda().eval()
        net.load_state_dict(ck["state"])

        def f(it):
            with torch.no_grad(), torch.autocast("cuda", dtype=torch.bfloat16):
                return net(torch.from_numpy(it["wave"])[None].cuda(), torch.from_numpy(X[it["i"]])[None].cuda())
        return f
    run("L3", setup_l3)

    def setup_qwen():
        import p1v4_b2 as B2
        K = json.load(open(f"{R}/b2local/b2local_dev.json"))["chosen_K"]
        block = json.load(open(f"{R}/b2local/examples.json", encoding="utf-8"))["blocks"][str(K)]
        tok, lm = B2.load_qwen()
        _, pre_ids = B2.prefix_ids(tok, block)
        L = pre_ids.shape[1]
        with torch.no_grad():
            cache = B2.encode_prefix(lm, pre_ids)
        res["qwen_K"] = K
        # prompts tokenised before timing (in its favour: a deployment would tokenise only the case)
        prompts = {it["j"]: [B2.question_ids(tok, B2.case_block(it["text"], it["asks"]), block, a[0])[1:]
                             for a in it["asks"]] for it in items}

        def f(it):
            for x, keep in prompts[it["j"]]:
                with torch.no_grad():
                    B2.case_logits(lm, x, cache, L, keep)
        return f
    run("qwen_cached_all_asked", setup_qwen)

    def total(*parts):
        return float(sum(res[p]["median_s"] for p in parts)) if all(p in res for p in parts) else None
    front = ("detector", "whisper_small_line", "ecapa_line")
    res["front_end_median_s"] = total(*front)
    res["totals_median_s"] = {"B1-strong": total(*front), "B2-local": total(*front, "qwen_cached_all_asked"),
                              "L1": total(*front, "L1"), "L2": total(*front, "voxturn_5q", "minilm_x3"),
                              "L3": total(*front, "L3", "minilm_x3")}
    res["errors"] = errors
    json.dump(res, open(out_path, "w"), indent=1)
    print(json.dumps(res, indent=1))


if __name__ == "__main__":
    main(sys.argv[1])
